import{_ as t,o as a,c as i,a5 as o}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"Sources, Citation, and Verification","description":"How Still Here separates research findings, personal experience, and untested hypotheses, how AI material is rechecked, and how to cite the book correctly.","frontmatter":{"title":"Sources, Citation, and Verification","description":"How Still Here separates research findings, personal experience, and untested hypotheses, how AI material is rechecked, and how to cite the book correctly.","updated":"2026-11-23T00:00:00.000Z"},"headers":[],"relativePath":"en/reference/sources-and-citation.md","filePath":"en/reference/sources-and-citation.md","lastUpdated":1795392000000}'),r={name:"en/reference/sources-and-citation.md"};function n(s,e,c,h,d,l){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="sources-citation-and-verification" tabindex="-1">Sources, Citation, and Verification <a class="header-anchor" href="#sources-citation-and-verification" aria-label="Permalink to &quot;Sources, Citation, and Verification&quot;">​</a></h1><p>This book does not want any sentence treated as beyond challenge. This page covers three things: how statements are classified, how often external material is rechecked, and how to cite and correct the book.</p><h2 id="three-kinds-of-statements" tabindex="-1">Three Kinds of Statements <a class="header-anchor" href="#three-kinds-of-statements" aria-label="Permalink to &quot;Three Kinds of Statements&quot;">​</a></h2><p><strong>Research findings</strong> come from published studies, official guidance, or specifications. They describe results obtained under particular samples, materials, measures, and conditions. They cannot be rewritten as a guarantee for one person. When the book cites them, it keeps the author, year, link, and limits; primary sources are used where they can be checked, and marketing pages are not accepted as a substitute.</p><p><strong>Personal experience</strong> proves only what the author lived through. It can be part of the evidence, but it is not a law: one failure does not show that everyone should avoid the same road, and one recovery does not show that one method works for everyone. Read a personal story as a scene, not a prescription.</p><p><strong>Untested hypotheses</strong> are inferences about the future, made by the author or the reader. They may be right, and the next experiment may overturn them. The book tries to mark “if … then …” conditions; a judgment without such a marker can be treated as a hypothesis.</p><p>When the three are mixed, the result is prose that sounds right and fails in use. While reading, ask first: which kind of statement is this?</p><h2 id="recheck-rules-for-ai-material" tabindex="-1">Recheck Rules for AI Material <a class="header-anchor" href="#recheck-rules-for-ai-material" aria-label="Permalink to &quot;Recheck Rules for AI Material&quot;">​</a></h2><p>AI products, model capabilities, prices, plans, protocols, and vendor policies change quickly. The book rechecks them by how fast they move:</p><ul><li><strong>30 days</strong>: usage policies, safety notices, product features, regions, and plans. Pages declare <code>source_review_interval: 30</code>.</li><li><strong>60 days</strong>: specifications, implementation guides, and fast-moving workflows.</li><li><strong>120 days</strong>: relatively stable concepts, research background, and historical facts.</li></ul><p>The rules:</p><ol><li>Prefer official documentation, formal specifications, or first-party announcements over second-hand blogs.</li><li>Record the verification date (<code>sources_checked</code>) separately from the text revision date (<code>updated</code>).</li><li>A product entry point is a page that can be rechecked, not a current feature list or an outcome guarantee.</li><li>Mark pages that can no longer be verified as historical; do not keep using them as current evidence.</li><li>Policies, prices, and capabilities must return to formal terms, official pages, and actual acceptance.</li></ol><p>If a product description here is out of date, please report it in the way described below.</p><h2 id="how-to-cite-this-book" tabindex="-1">How to Cite This Book <a class="header-anchor" href="#how-to-cite-this-book" aria-label="Permalink to &quot;How to Cite This Book&quot;">​</a></h2><p>When citing, include the title, author, edition, date, and URL, and note that the text is CC BY-NC 4.0:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Han Xiankai. Still Here: A Field Guide to Beginning Again. Edition 1.1.0. 23 November 2026.</span></span>
<span class="line"><span>https://byoungd.github.io/up/en/</span></span></code></pre></div><p>Chinese edition:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>韩先凯. 人生进阶指南：一个普通人的失败、恢复与重新学习. 1.1.0 版. 2026-11-23.</span></span>
<span class="line"><span>https://byoungd.github.io/up/</span></span></code></pre></div><p>The repository root contains <a href="https://github.com/byoungd/up/blob/main/CITATION.cff" target="_blank" rel="noreferrer"><code>CITATION.cff</code></a> with machine-readable citation data. The book has no DOI and no ISBN; please do not add one. When citing a specific chapter, include the chapter title and page address so a reader can return to the text.</p><h2 id="reporting-a-source-error" tabindex="-1">Reporting a Source Error <a class="header-anchor" href="#reporting-a-source-error" aria-label="Permalink to &quot;Reporting a Source Error&quot;">​</a></h2><p>If you find that:</p><ul><li>a cited research finding does not match the original;</li><li>a link is broken or points to a different page;</li><li>a product description is out of date;</li><li>the Chinese and English editions disagree on a fact;</li></ul><p>use the <a href="https://github.com/byoungd/up/issues/new/choose" target="_blank" rel="noreferrer">issue templates</a> and include the page, the sentence, the source you believe is correct, and the date you checked it. For personal data, unauthorised images, or security problems, do not post publicly; use the private route in <code>SECURITY.md</code>.</p><p>Maintainers verify the source first and then change the text. Changing a date without checking the content does not count as verification.</p><h2 id="bibliography" tabindex="-1">Bibliography <a class="header-anchor" href="#bibliography" aria-label="Permalink to &quot;Bibliography&quot;">​</a></h2><p>The subject list of sources is in the <a href="./bibliography">Bibliography</a>. It includes only material the book actually cites and is deliberately selective. Papers and books are not distributed with the repository; readers reach them through their DOI or official link.</p>`,26)])])}const f=t(r,[["render",n]]);export{u as __pageData,f as default};
